# ---------------- metric catalog ----------------
SF="Summary filters: Hisaab week = column week (Mon-Sun); City B2, Fuel B4, Product B5, ELC B6, Active B7 ('*' = all)"
WF="WBR filters: Hisaab week = column week; City = row; Product = block header (row 5); Active C1; In-car-recovery C2"
WF2="WBR filters: Hisaab week = column week; City = row; Product = block header (row 5)"
J0="None - MV row only (analytics.collections_bad_debt_mv, for_collections = 1)"
JR="mv_daily_recovery r ON r.employee_id = m.partner_etm AND date_trunc('week', r.date) = m.hissab_week (pre-aggregated per partner-week)"
JML="mv_collections_calling_masterlist ml ON ml.partner_et_id = m.partner_etm AND ml.week = m.hissab_week (DISTINCT ON latest snapshot_date)"
JRC="recovery_cars r JOIN fleet_driver fd ON fd.id = r.driver_id; fd.employee_id = m.partner_etm; week window: r.created_at < hissab_week+7 AND (status open OR r.updated_at >= hissab_week)"
JAL="ssot_alloc_dealloc_base s ON s.employee_id = m.partner_etm AND s.allocation_date <= hissab_week+6 (latest); mv_deposits_raw x ON x.employee_id = m.partner_etm AND x.date <= alloc_date"
JNP="collections_bad_debt_mv history window: partition by partner_etm, order by hissab_week, range 14 days preceding .. 1 day preceding"
JCT="City_Targets tab: Week Start = column week, City, Product Type"
# status values
OK='MV - correct'; BAD='MV - needs correction'; ADD='Missing in MV - added in query'; DER='Derived in query from MV columns'; BIZ='Business input (City_Targets)'; LOGIC='MV - logic decision needed'; NOSRC='No PG source'
